mapper.select:
SELECT t.post_id AS postId, MAX(CASE WHEN t.rn = 1 THEN t.view_count END) AS lastViewCount, MAX(CASE WHEN t.rn = 1 THEN t.like_count END) AS lastLikeCount, MAX(CASE WHEN t.rn = 1 THEN t.comment_count END) AS lastCommentCount, COUNT(*) AS windowRowCount, COALESCE(SUM(t.raw_score), 0) AS windowScoreSum FROM ( SELECT s.post_id, s.view_count, s.like_count, s.comment_count, s.raw_score, ROW_NUMBER() OVER (PARTITION BY s.post_id ORDER BY s.stat_hour DESC) AS rn FROM stats_post_hourly s WHERE s.stat_hour < #{before} AND s.post_id IN
#{postId}
) t WHERE t.rn <= #{windows} GROUP BY t.post_id
